  only: ['alone', 'single', 'just'],
  other: ['another', 'else'],
  okay: ['ok', 'alright', 'all right'],
  'thank you': ['thanks'],
  'a little': ['a bit', 'a little bit'],
  'a lot': ['lots', 'a lot of', 'lots of', 'much', 'so much'],
  much: ['so much'],
  maybe: ['perhaps', 'possibly'],
  also: ['too', 'as well'],
  'too much': ['too many'],
  difficult: ['hard'],
  actually: ['in fact'],
  but: ['however'],
  'there is': ['there are'],
  'there are': ['there is'],
  'it is': ['this is', 'that is', "that's"],
  hello: ['hi'],
  'of course': ['sure', 'certainly'],
  so: ['therefore', 'so then'],
  ready: ['all set'],
  almost: ['nearly'],
  someone: ['somebody'],
  nobody: ['no one'],
  everyone: ['everybody'],
  small: ['little', 'tiny'],
  pretty: ['beautiful'],
  great: ['awesome'],
  happy: ['glad'],
  afterwards: ['afterward', 'after that'],
  incredible: ['amazing'],
  toward: ['towards'],
